@icontract.ensure(lambda arr, i, j, result: len(result) == len(arr) and all(
    result[k] == arr[k] for k in range(len(arr)) if k != i and k != j))
def swap(arr: List[int], i: int, j: int) -> List[int]:
    result = list(arr)
    tmp = result[i]
    result[i] = result[j]
    result[j] = tmp
    return result
